#!/bin/bash
# Vendors the Lucide icons named in crates/cancho-ui-ir/vendor/lucide/NAMES (one per line) at one pinned release tag, from the official repository
# only (https://github.com/lucide-icons/lucide, raw files at that tag): scripts/vendor_lucide.sh 1.67.0
# It writes each icon's SVG text verbatim, the repository's LICENSE (ISC and the Feather MIT part: both notices stay), a VERSION file with the tag and the
# commit, and crates/cancho-ui-ir/src/icon_set.rs (the table the compiler reads, generated: do not edit). It refuses an SVG that is not plain.
set -euo pipefail
cd "$(dirname "$0")/.."
tag="${1:?usage: vendor_lucide.sh <tag, e.g. 1.67.0>}"
dir=crates/cancho-ui-ir/vendor/lucide
names="$dir/NAMES"
[ -f "$names" ] || { echo "$names is missing"; exit 2; }
commit=$(curl -fsS "https://api.github.com/repos/lucide-icons/lucide/git/ref/tags/$tag" | python3 -c 'import json,sys; print(json.load(sys.stdin)["object"]["sha"])')
base="https://raw.githubusercontent.com/lucide-icons/lucide/$tag"
rm -f "$dir"/*.svg
while read -r n; do
    case "$n" in ''|\#*) continue;; esac
    case "$n" in *[!a-z0-9-]*) echo "bad icon name $n"; exit 2;; esac
    curl -fsS "$base/icons/$n.svg" -o "$dir/$n.svg"
done < "$names"
curl -fsS "$base/LICENSE" -o "$dir/LICENSE"
grep -q "ISC License" "$dir/LICENSE" && grep -q "The MIT License (MIT)" "$dir/LICENSE" || { echo "LICENSE is not the ISC + Feather MIT text"; exit 2; }
printf 'lucide %s\ncommit %s\nsource https://github.com/lucide-icons/lucide\n' "$tag" "$commit" > "$dir/VERSION"
python3 - "$dir" <<'PY'
import re, sys, os
d = sys.argv[1]
names = [l.strip() for l in open(d + "/NAMES") if l.strip() and not l.startswith("#")]
out = ["// Generated by scripts/vendor_lucide.sh from crates/cancho-ui-ir/vendor/lucide (Lucide, ISC; Feather parts MIT: see vendor/lucide/LICENSE and THIRD_PARTY.md). Do not edit.",
       "pub const SET: &[(&str, &str)] = &["]
ok_tags = {"path", "circle", "rect", "line", "polyline"}
for n in sorted(names):
    t = open(f"{d}/{n}.svg").read()
    assert t.lstrip().startswith("<svg") and t.rstrip().endswith("</svg>"), n
    for bad in ("<script", "<image", "href", "xlink", "<style", "data:", "<use", "<foreignObject", "on", "<!"):
        if bad == "on":
            assert not re.search(r"\son[a-z]+=", t), (n, "event attribute")
        else:
            assert bad not in t, (n, bad)
    body = t[t.index(">") + 1 : t.rindex("</svg>")]
    for tag in re.findall(r"<\s*([a-zA-Z0-9]+)", body):
        assert tag in ok_tags, (n, tag)
    out.append(f'    ("{n}", include_str!("../vendor/lucide/{n}.svg")),')
out.append("];")
open("crates/cancho-ui-ir/src/icon_set.rs", "w").write("\n".join(out) + "\n")
print(len(names), "icons")
PY
python3 - "$dir" "$tag" "$commit" <<'PY'
import sys
d, tag, commit = sys.argv[1:4]
names = sorted(l.strip() for l in open(d + "/NAMES") if l.strip() and not l.startswith("#"))
lic = open(d + "/LICENSE").read().strip()
body = f"""# Third-party material

## Lucide icons (the `Icon` element, docs/structure.md 12.0q)

* **What:** {len(names)} line icons, written verbatim as SVG text in `crates/cancho-ui-ir/vendor/lucide/` and compiled into the page by the `Icon` element.
* **Source:** <https://github.com/lucide-icons/lucide>, release tag `{tag}`, commit `{commit}`; each file is `icons/<name>.svg` at that tag. Nothing is fetched at build or run time. `scripts/vendor_lucide.sh {tag}` re-creates the files and this list.
* **Licence:** ISC (Lucide Icons and Contributors), and the MIT licence of the Feather project for the icons Lucide derives from Feather. The credit line below is a condition of both licences: it stays with every copy of the icons. The full text is `crates/cancho-ui-ir/vendor/lucide/LICENSE`, repeated here.
* **Icons used:** {", ".join("`" + n + "`" for n in names)}.

```
{lic}
```
"""
open("THIRD_PARTY.md", "w").write(body)
PY
